import React, { createContext, useContext, useState, useEffect } from 'react';
import axios from 'axios';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('token'));
  const [isLoading, setIsLoading] = useState(true);

  // Configure axios defaults
  useEffect(() => {
    if (token) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      const storedUser = localStorage.getItem('user');
      if (storedUser) {
        try {
          setUser(JSON.parse(storedUser));
        } catch (error) {
          console.error('Error parsing stored user:', error);
          localStorage.removeItem('user');
        }
      }
    } else {
      delete axios.defaults.headers.common['Authorization'];
    }
    setIsLoading(false);
  }, [token]);

  const login = async (username, password) => {
    try {
      const response = await axios.post('/api/auth/login', {
        username,
        password
      });

      // Now expect { token, user, status }
      const { token: newToken, user: userDTO, status } = response.data;

      if (status === 'PENDING_VERIFICATION') {
        throw new Error('Account is not verified yet. Please wait for admin approval.');
      }

      if (status === 'ACCOUNT_DISABLED') {
        throw new Error('Account is disabled. Please contact admin.');
      }

      if (newToken && userDTO) {
        setToken(newToken);
        localStorage.setItem('token', newToken);

        // Save cleaned user data (no password)
        setUser(userDTO);
        localStorage.setItem('user', JSON.stringify(userDTO));

        axios.defaults.headers.common['Authorization'] = `Bearer ${newToken}`;

        return { success: true, data: userDTO };
      }

      throw new Error('Invalid response from server');
    } catch (error) {
      console.error('Login error:', error);

      if (error.response) {
        const errorMessage = error.response.data?.error || 'Login failed';
        throw new Error(errorMessage);
      }

      throw error;
    }
  };

  const register = async (username, email, password) => {
    try {
      const response = await axios.post('/api/auth/register', {
        username,
        email,
        password
      });

      return { 
        success: true, 
        data: response.data,
        message: response.data.message || 'Registration successful. Please wait for admin approval.'
      };
    } catch (error) {
      console.error('Registration error:', error);

      if (error.response) {
        const errorMessage = error.response.data?.error || 'Registration failed';
        throw new Error(errorMessage);
      }

      throw error;
    }
  };

  const logout = () => {
    setToken(null);
    setUser(null);
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    delete axios.defaults.headers.common['Authorization'];
  };

  // Updated role check since backend returns roles: ["ADMIN", "VENDOR"]
  const hasRole = (role) => {
    if (!user || !user.roles) return false;
    return user.roles.includes(role) || user.roles.includes(`ROLE_${role}`);
  };

  const isVendor = () => hasRole('VENDOR');
  const isAdmin = () => hasRole('ADMIN');

  const value = {
    user,
    token,
    isLoading,
    login,
    register,
    logout,
    hasRole,
    isVendor,
    isAdmin,
    isAuthenticated: !!token && !!user
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
